#!/usr/bin/env node
// @effect-diagnostics nodeBuiltinImport:off - A build step with no Effect runtime.
// Writes src/embeddedWasm.generated.ts from vendor/, so Node loads the wasm with no file to ship.
import * as NodeFS from "node:fs";

const read = (file: string) =>
  NodeFS.readFileSync(new URL(`../vendor/${file}`, import.meta.url)).toString("base64");

NodeFS.writeFileSync(
  new URL("../src/embeddedWasm.generated.ts", import.meta.url),
  [
    "// Generated by scripts/embed-wasm.ts from vendor/. Do not edit; rerun it after a wasm build.",
    // Laid out as the formatter would, so a regenerated file needs no reformatting.
    `export const GHOSTTY_VT_WASM_BASE64 =\n  "${read("ghostty-vt.wasm")}";`,
    `export const GHOSTTY_WRITE_PTY_WASM_BASE64 =\n  "${read("ghostty-write-pty.wasm")}";`,
    "",
  ].join("\n"),
);
